  it("versions presence preferences, throttles human activity, and emits one event per change", async () => {
    const owner = await repo.createUser({
      email: `presence-owner-${randomUUID()}@example.com`,
      displayName: "Presence Owner"
    });
    const outsider = await repo.createUser({
      email: `presence-outsider-${randomUUID()}@example.com`
    });
    const team = await repo.createTeam(
      { userId: owner.id },
      { name: "Presence Team" }
    );

    await expect(
      repo.setTeamPresence(
        { userId: outsider.id },
        {
          teamId: team.id,
          mode: "manual",
          manualPresenceStatus: "do_not_disturb",
          expectedVersion: 1
        }
      )
    ).resolves.toBeNull();

    const updated = await repo.setTeamPresence(
      { userId: owner.id },
      {
        teamId: team.id,
        mode: "manual",
        manualPresenceStatus: "do_not_disturb",
        expectedVersion: 1
      }
    );
    expect(updated).toMatchObject({
      userId: owner.id,
      presenceMode: "manual",
      manualPresenceStatus: "do_not_disturb",
      presenceVersion: 2
    });
    await expect(
      repo.setTeamPresence(
        { userId: owner.id },
        {
          teamId: team.id,
          mode: "manual",
          manualPresenceStatus: "out_of_office",
          expectedVersion: 1
        }
      )
    ).resolves.toBeNull();

    await expect(
      repo.recordTeamHumanActivity({ userId: owner.id }, [team.id, team.id])
    ).resolves.toEqual([team.id]);
    await expect(
      repo.recordTeamHumanActivity({ userId: owner.id }, [team.id])
    ).resolves.toEqual([]);
    await expect(
      repo.recordTeamHumanActivity({ userId: outsider.id }, [team.id])
    ).resolves.toEqual([]);

    const manualEvents = await pool.query<{ count: string }>(
      `select count(*)::text as count
         from collaboration_outbox
        where team_id = $1
          and family = 'team_presence_changed'`,
      [team.id]
    );
    expect(manualEvents.rows[0]?.count).toBe("1");

    const roster = await repo.listTeamRoster({ userId: owner.id }, team.id);
    expect(roster).toHaveLength(1);
    expect(roster?.[0]).toMatchObject({
      userId: owner.id,
      presenceMode: "manual",
      manualPresenceStatus: "do_not_disturb",
      presenceVersion: 2
    });
    expect(typeof roster?.[0]?.lastHumanActivityAt).toBe("string");

    await expect(
      repo.setTeamPresence(
        { userId: owner.id },
        {
          teamId: team.id,
          mode: "auto",
          manualPresenceStatus: "do_not_disturb",
          expectedVersion: 2
        }
      )
    ).resolves.toMatchObject({
      presenceMode: "auto",
      presenceVersion: 3
    });
    await pool.query(
      `update team_memberships
          set last_human_activity_at = now() - interval '2 minutes'
        where team_id = $1 and user_id = $2`,
      [team.id, owner.id]
    );
    await expect(
      repo.recordTeamHumanActivity({ userId: owner.id }, [team.id])
    ).resolves.toEqual([team.id]);

    const events = await pool.query<{ count: string }>(
      `select count(*)::text as count
         from collaboration_outbox
        where team_id = $1
          and family = 'team_presence_changed'`,
      [team.id]
    );
    expect(events.rows[0]?.count).toBe("3");
  });

  it("rolls back Team mutations when collaboration outbox insertion fails", async () => {
    const owner = await repo.createUser({
      email: `outbox-owner-${randomUUID()}@example.com`
    });
    const admin = await repo.createUser({
      email: `outbox-admin-${randomUUID()}@example.com`
    });
    const team = await repo.createTeam(
      { userId: owner.id },
      { name: "Outbox Atomicity Team" }
    );
    const membership = (
      await inviteExistingTeamMember({
        actorUserId: owner.id,
        teamId: team.id,
        user: admin,
        role: "admin"
      })
    ).membership;
    const countsBefore = await pool.query<{
      outbox: string;
      audits: string;
    }>(
      `select
         (select count(*) from collaboration_outbox where team_id = $1)::text as outbox,
         (select count(*) from audit_events where action = 'team.member.role_changed' and metadata ->> 'teamId' = $1::text)::text as audits`,
      [team.id]
    );
    const removeTrigger = await installRejectingTrigger({
      table: "collaboration_outbox",
      operation: "insert",
      predicate: `new.resource_type = 'team_membership' and new.resource_id = '${membership.id}'`
    });
    try {
      await expect(
        repo.updateTeamMemberRole(
          { userId: owner.id },
          {
            teamId: team.id,
            userId: admin.id,
            role: "member",
            expectedVersion: membership.version
          }
        )
      ).rejects.toThrow();
    } finally {
      await removeTrigger();
    }

    await expect(
      repo.getTeamMembership({ userId: admin.id }, team.id)
    ).resolves.toMatchObject({ role: "admin", version: membership.version });
    await expect(
      pool.query<{
        outbox: string;
        audits: string;
      }>(
        `select
           (select count(*) from collaboration_outbox where team_id = $1)::text as outbox,
           (select count(*) from audit_events where action = 'team.member.role_changed' and metadata ->> 'teamId' = $1::text)::text as audits`,
        [team.id]
      )
    ).resolves.toMatchObject({ rows: countsBefore.rows });

    await expect(
      repo.updateTeamMemberRole(
        { userId: owner.id },
        {
          teamId: team.id,
          userId: admin.id,
          role: "member",
          expectedVersion: membership.version
        }
      )
    ).resolves.toMatchObject({
      role: "member",
      version: membership.version + 1
    });
    const countsAfter = await pool.query<{
      outbox: string;
      audits: string;
    }>(
      `select
         (select count(*) from collaboration_outbox where team_id = $1)::text as outbox,
         (select count(*) from audit_events where action = 'team.member.role_changed' and metadata ->> 'teamId' = $1::text)::text as audits`,
      [team.id]
    );
    expect(Number(countsAfter.rows[0]!.outbox)).toBe(
      Number(countsBefore.rows[0]!.outbox) + 1
    );
    expect(Number(countsAfter.rows[0]!.audits)).toBe(
      Number(countsBefore.rows[0]!.audits) + 1
    );
  });

  it("rolls back API token lifecycle changes when audit insertion fails", async () => {
    const user = await repo.createUser({
      email: `api-token-audit-rollback-${randomUUID()}@example.com`
    });
    const missingActorId = randomUUID();
    const failedCreateHash = `hash-${randomUUID()}-${randomUUID()}`;

    await expect(
      repo.createApiToken({
        ownerUserId: user.id,
        name: "Rollback Create",
        tokenHash: failedCreateHash,
        tokenPrefix: "cmt_fail",
        audit: {
          actorUserId: missingActorId,
          actorType: "user"
        }
      })
    ).rejects.toThrow();
    expect(await repo.listApiTokens(user.id)).toEqual([]);

    const tokenHash = `hash-${randomUUID()}-${randomUUID()}`;
    const token = await repo.createApiToken({
      ownerUserId: user.id,
      name: "Rollback Revoke",
      tokenHash,
      tokenPrefix: "cmt_keep"
    });
    await expect(
      repo.revokeApiToken(user.id, token.id, {
        actorUserId: missingActorId,
        actorType: "user"
      })
    ).rejects.toThrow();
    expect(await repo.listApiTokens(user.id)).toEqual([token]);
  });

  it("manages auth sessions through the Drizzle-backed repository slice", async () => {
    const email = `auth-session-${randomUUID()}@example.com`;
    const user = await repo.createUser({
      email,
      displayName: "Session User"
    });
    const activeHash = `${randomUUID()}-${randomUUID()}`;
    const revokedHash = `${randomUUID()}-${randomUUID()}`;
    const expiredHash = `${randomUUID()}-${randomUUID()}`;
    const disabledHash = `${randomUUID()}-${randomUUID()}`;

    await repo.createSession(
      user.id,
      activeHash,
      new Date(Date.now() + 60_000)
    );
    expect(await repo.getSessionUser(activeHash)).toMatchObject({
      id: user.id,
      email,
      displayName: "Session User",
      passwordHash: null
    });

    await repo.createSession(
      user.id,
      revokedHash,
      new Date(Date.now() + 60_000)
    );
    await repo.revokeSession(revokedHash);
    expect(await repo.getSessionUser(revokedHash)).toBeNull();
    await repo.revokeSession(revokedHash);

    await repo.createSession(
      user.id,
      expiredHash,
      new Date(Date.now() - 60_000)
    );
    expect(await repo.getSessionUser(expiredHash)).toBeNull();

    await repo.createSession(
      user.id,
      disabledHash,
      new Date(Date.now() + 60_000)
    );
    await pool.query("update users set disabled_at = now() where id = $1", [
      user.id
    ]);
    expect(await repo.getSessionUser(disabledHash)).toBeNull();

    const deletedUser = await repo.createUser({
      email: `auth-session-deleted-${randomUUID()}@example.com`
    });
    const deletedHash = `${randomUUID()}-${randomUUID()}`;
    await repo.createSession(
      deletedUser.id,
      deletedHash,
      new Date(Date.now() + 60_000)
    );
    await pool.query("update users set deleted_at = now() where id = $1", [
      deletedUser.id
    ]);
    expect(await repo.getSessionUser(deletedHash)).toBeNull();
  });

  it("maps external AuthKit identities by provider user id instead of email", async () => {
    const existingEmail = `external-auth-existing-${randomUUID()}@example.com`;
    await repo.createUser({
      email: existingEmail,
      displayName: "Existing Local User"
    });

    await expect(
      repo.upsertExternalAuthSession({
        provider: "workos_authkit",
        providerEnvironment: "test",
        providerUserId: `workos-${randomUUID()}`,
        email: existingEmail,
        emailVerified: true,
        displayName: "External Same Email"
      })
    ).rejects.toThrow(
      "External identity is not linked to the existing Koed account"
    );

    const providerUserId = `workos-${randomUUID()}`;
    const created = await repo.upsertExternalAuthSession({
      provider: "workos_authkit",
      providerEnvironment: "test",
      providerUserId,
      email: `external-auth-created-${randomUUID()}@example.com`,
      emailVerified: true,
      displayName: "External User",
      profile: {
        safe: true,
        refresh_token: "should-not-be-supplied-by-route"
      }
    });
    const seenAgain = await repo.upsertExternalAuthSession({
      provider: "workos_authkit",
      providerEnvironment: "test",
      providerUserId,
      email: `external-auth-renamed-${randomUUID()}@example.com`,
      emailVerified: false,
      displayName: "External Renamed"
    });

    expect(created.createdUser).toBe(true);
    expect(seenAgain.createdUser).toBe(false);
    expect(seenAgain.user.id).toBe(created.user.id);
    const identity = await repo.getExternalAuthIdentity({
      provider: "workos_authkit",
      providerEnvironment: "test",
      providerUserId
    });
    expect(identity).toMatchObject({
      userId: created.user.id,
      emailVerified: false,
      displayName: "External Renamed"
    });
    expect(JSON.stringify(identity?.profile)).not.toContain("refresh_token");
  });

